INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('afd22cab-066c-49a2-ab8a-1e9cd50ec3d1','bbbbbbbb-0001-0000-0000-000000000001',10,'*(UNIDOMPEDRO)* Aula prática de biologia celular: alunos analisam células eucarióticas animais ao microscópio óptico e discutem afirmações sobre organelas.','Analise as afirmações: **I.** O núcleo contém o material genético e regula as atividades celulares via expressão gênica. **II.** Mitocôndrias têm DNA próprio e produzem ATP por respiração aeróbica. **III.** Lisossomos sintetizam proteínas e lipídios e transportam substâncias intracelulares. **IV.** O complexo de Golgi degrada peróxido de hidrogênio. Marque a alternativa com **todas** as assertivas corretas.','multipla_escolha','**I — Verdadeira.** Núcleo com envelope nuclear controla a expressão gênica. **II — Verdadeira.** Mitocôndrias têm DNA próprio; ATP via fosforilação oxidativa nas cristas mitocondriais. **III — Falsa.** Lisossomos fazem **digestão intracelular**, não síntese. Proteínas são sintetizadas nos ribossomos; lipídios no REL. **IV — Falsa.** H₂O₂ é degradado pelos **peroxissomos**, não pelo complexo de Golgi. **Alternativa correta: C (apenas I e II).**','ALBERTS, B. et al. Fundamentos da biologia celular. 3. ed. Porto Alegre: Artmed, 2011. JUNQUEIRA, L. C.; CARNEIRO, J. Biologia celular e molecular. 9. ed. Rio de Janeiro: Guanabara Koogan, 2013.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('cb557cfa-41a7-41d5-aac2-b8057a236960','afd22cab-066c-49a2-ab8a-1e9cd50ec3d1','A','Apenas II e III.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('85bdaf89-2890-4d58-9412-dc7386742737','afd22cab-066c-49a2-ab8a-1e9cd50ec3d1','B','Apenas I e IV.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('11509f59-3b41-4cbb-8b50-a644a10891af','afd22cab-066c-49a2-ab8a-1e9cd50ec3d1','C','Apenas I e II.',true,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('bf5cdf02-780a-4d0b-ab20-ea65aa1a0f1a','afd22cab-066c-49a2-ab8a-1e9cd50ec3d1','D','Apenas III e IV.',false,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('d48470eb-f9f0-4531-b8d4-3de9a03bd1d1','bbbbbbbb-0001-0000-0000-000000000001',11,'*(UNITPAC)* Idoso, 65 anos: cansaço nas pernas ao final do dia, inchaço nos tornozelos, peso nos membros inferiores. Exame físico revela varicosidades leves.','Considerando a anatomia do retorno venoso dos membros inferiores, qual estrutura é mais diretamente relacionada a esse quadro?','multipla_escolha','As **veias safena magna e parva** são os principais vasos do sistema venoso **superficial** dos membros inferiores. A incompetência de suas válvulas favorece estase venosa, varicosidades, edema e dor. São a estrutura mais frequentemente acometida na insuficiência venosa crônica. **Alternativa correta: A.**','NETTER, F. H. Atlas de Anatomia Humana. 7. ed. Rio de Janeiro: Elsevier, 2019.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('537ba663-620b-4793-a274-6aa2693cc7eb','d48470eb-f9f0-4531-b8d4-3de9a03bd1d1','A','Veia safena parva e magna, vasos superficiais que drenam a perna e a região poplítea.',true,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('75cbc59b-47f2-434d-8394-63714127bc6c','d48470eb-f9f0-4531-b8d4-3de9a03bd1d1','B','Artéria femoral comum, responsável pela irrigação principal do membro inferior.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('0bdbf5c3-94ce-4e7a-ad54-7aec79079660','d48470eb-f9f0-4531-b8d4-3de9a03bd1d1','C','Veia cava inferior, principal via de drenagem sanguínea da metade inferior do corpo.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('a11251a2-8fe5-4d12-abd8-ca62ed80a920','d48470eb-f9f0-4531-b8d4-3de9a03bd1d1','D','Artéria tibial posterior, responsável pela irrigação da região plantar e dorsal do pé.',false,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('f715cbe8-4f14-4679-b99f-c97236432476','bbbbbbbb-0001-0000-0000-000000000001',12,'*(AFYA Cruzeiro do Sul)* Alunos registram ECG com ondas P, QRS e T regulares. Um estudante pergunta: "Por que a despolarização ventricular, observada no ECG, ocorre **antes** da ejeção do sangue?"','Assinale a opção que responde corretamente ao questionamento.','multipla_escolha','A despolarização ventricular (complexo QRS) precede a ejeção porque **inicia a contração ventricular**, gerando aumento progressivo da pressão intraventricular. Quando a pressão supera a pressão arterial (aorta/pulmonar), as **valvas semilunares** se abrem e o sangue é ejetado. Sem a despolarização, não há contração nem aumento de pressão. **Alternativa correta: D.**','GUYTON, A. C.; HALL, J. E. Tratado de Fisiologia Médica. 14. ed. Rio de Janeiro: Elsevier, 2021.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('9b3e6dd8-35a9-4b1c-a0fe-347b46a7dd14','f715cbe8-4f14-4679-b99f-c97236432476','A','Relaciona-se ao fato de a despolarização atrial sincronizar-se com a contração ventricular.',false,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('35917b40-d7fb-4b88-95bb-b622143c302a','f715cbe8-4f14-4679-b99f-c97236432476','B','Relaciona-se à repolarização ventricular, que gera queda de pressão e abre as valvas atrioventriculares.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('01be80ec-0be9-4e78-b268-83ec6fa899e1','f715cbe8-4f14-4679-b99f-c97236432476','C','Relaciona-se à onda T, que marca o relaxamento ventricular e o retorno do sangue venoso.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('6156c621-4ea3-48f6-a05e-11c1b7fabd81','f715cbe8-4f14-4679-b99f-c97236432476','D','Relaciona-se à necessidade do estímulo elétrico ventricular deflagrar a contração, elevando a pressão até abrir as valvas semilunares.',true,4);
INSERT INTO public.questao (id,prova_id,ordem_na_prova,enunciado_apoio,enunciado,formato,explicacao,referencia,imagem_url,disciplina,periodo,fonte,status,revisado) VALUES ('ac4f7a44-be20-4f71-ba38-59cd4a35499b','bbbbbbbb-0001-0000-0000-000000000001',13,'*(UNIDOMPEDRO)* Alunos analisam dois potenciais de ação cardíacos: um com despolarização **rápida** (subida abrupta) e outro com despolarização **lenta** (subida gradual). Professor pede que relacionem íons, canais e regiões cardíacas.','Compare os potenciais de ação de resposta rápida e lenta quanto aos íons, canais e regiões cardíacas, e assinale a alternativa correta.','multipla_escolha','- **Resposta rápida**: canais rápidos de **Na⁺** → despolarização abrupta → ocorre em **ventrículos, átrios e fibras de Purkinje**. - **Resposta lenta**: canais de **Ca²⁺ tipo L** e corrente If (Na⁺) → despolarização gradual → ocorre nos **nódulos SA e AV** (marcapassos). Essa diferença explica a condução rápida nas fibras contráteis e a automacidade dos marcapassos. **Alternativa correta: A.**','HALL, J. E.; HALL, M. E. Guyton & Hall. Tratado de Fisiologia Médica. 14. ed. 2021.',NULL,'SOI',1,'Afya SOI I N1 2025.2','ativa',true);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('5cf14a87-e5e0-4b42-8d23-d3d6da395965','ac4f7a44-be20-4f71-ba38-59cd4a35499b','A','Resposta rápida: canais de Na⁺ em ventrículos, átrios e Purkinje; lenta: Ca²⁺ nos nódulos SA e AV.',true,1);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('85e40ff2-32a5-46ff-b25e-97b5a71c708f','ac4f7a44-be20-4f71-ba38-59cd4a35499b','B','Resposta rápida ocorre apenas em células musculares atriais e ventriculares, sem Purkinje.',false,2);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('b428f1f1-cca3-4f94-b08e-84e3ae80a390','ac4f7a44-be20-4f71-ba38-59cd4a35499b','C','Resposta rápida: canais de Ca²⁺ nos nódulos SA e AV; lenta: canais de Na⁺ em ventrículos e átrios.',false,3);
INSERT INTO public.alternativa (id,questao_id,letra,texto,correta,ordem) VALUES ('1ef512bd-dcdc-4e88-aaf7-2359230e0936','ac4f7a44-be20-4f71-ba38-59cd4a35499b','D','Resposta lenta depende de canais de K⁺ e ocorre em ventrículos e átrios.',false,4);;
